const labels={fa:{title:'مدیریت نظرات',intro:'نظرهای محصولات و مقاله‌ها را بررسی کنید؛ انتشار، پنهان‌کردن و پاسخ‌دادن از همین‌جا انجام می‌شود.',pending:'در انتظار بررسی',approved:'منتشرشده',rejected:'منتشرنشده',all:'همه',empty:'نظری در این بخش نیست.',reply:'پاسخ مدیر',approve:'تأیید و انتشار',reject:'عدم انتشار',save:'ذخیره پاسخ',previous:'قبلی',next:'بعدی',product:'محصول',article:'مقاله',preview:'برای مدیریت نظرات وارد حساب مدیر شوید.',loading:'در حال دریافت نظرات…',error:'دریافت یا ذخیره نظرات انجام نشد.',conflict:'این نظر در پنل دیگری تغییر کرده؛ فهرست تازه دریافت شد.',saved:'تغییر نظر ذخیره شد.',page:'صفحه'},en:{title:'Comment moderation',intro:'Review product and article comments, publish or hide them, and respond here.',pending:'Awaiting moderation',approved:'Published',rejected:'Unpublished',all:'All',empty:'No comments in this view.',reply:'Administrator reply',approve:'Approve and publish',reject:'Do not publish',save:'Save reply',previous:'Previous',next:'Next',product:'Product',article:'Article',preview:'Sign in as an administrator to moderate comments.',loading:'Loading comments…',error:'Could not load or save comments.',conflict:'This comment changed in another panel. The list was refreshed.',saved:'Comment updated.',page:'Page'},it:{title:'Moderazione commenti',intro:'Controlla i commenti di prodotti e articoli, pubblicali o nascondili e rispondi qui.',pending:'Da moderare',approved:'Pubblicati',rejected:'Non pubblicati',all:'Tutti',empty:'Nessun commento in questa vista.',reply:'Risposta amministratore',approve:'Approva e pubblica',reject:'Non pubblicare',save:'Salva risposta',previous:'Precedente',next:'Successiva',product:'Prodotto',article:'Articolo',preview:'Accedi come amministratore per moderare i commenti.',loading:'Caricamento commenti…',error:'Impossibile caricare o salvare i commenti.',conflict:'Commento modificato in un altro pannello. Elenco aggiornato.',saved:'Commento aggiornato.',page:'Pagina'}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function commentsAdminView({lang,readonly,api,frame,isCurrent}){
 const c=labels[lang];let page=1,filter='pending',message='',saving=false;
 const title=item=>Array.isArray(item.targetTitle)?item.targetTitle[({fa:0,en:1,it:2})[lang]]:item.targetTitle?.[lang]||item.target;
 async function load(){
  frame('<p class="adm-eyebrow">PERSIA COMMUNITY / ADMIN</p><h1>'+esc(c.title)+'</h1><p>'+esc(c.intro)+'</p><p role="status">'+esc(readonly?c.preview:c.loading)+'</p>');if(readonly)return;
  try{const data=await api('/api/admin/comments?'+new URLSearchParams({status:filter,page:String(page)}));if(!isCurrent())return;
   frame('<div id="admin-comments"><p class="adm-eyebrow">PERSIA COMMUNITY / ADMIN</p><h1>'+esc(c.title)+'</h1><p>'+esc(c.intro)+'</p><div class="adm-comment-filters">'+['pending','approved','rejected','all'].map(s=>'<button type="button" class="adm-button '+(s===filter?'primary':'secondary')+'" data-comment-filter="'+s+'" aria-pressed="'+(s===filter)+'">'+esc(c[s])+'</button>').join('')+'</div><p role="status">'+esc(message)+'</p>'+(!data.items.length?'<p>'+esc(c.empty)+'</p>':data.items.map(item=>'<article class="adm-comment-card" data-comment-id="'+item.id+'"><div class="adm-comment-meta"><strong>'+esc(item.author)+'</strong><span>'+esc(c[item.status])+'</span><time>'+esc(new Intl.DateTimeFormat(lang==='fa'?'fa-IR':lang,{dateStyle:'medium',timeZone:'Europe/Rome'}).format(new Date(item.createdAt)))+'</time></div><a href="/'+(item.kind==='product'?'products':'blog')+'/'+esc(item.target)+'?lang='+lang+'#comments" target="_blank" rel="noopener">'+esc(c[item.kind])+' · '+esc(title(item))+' ↗</a>'+(item.rating?'<p>'+item.rating+' / 5 ★</p>':'')+'<p class="adm-comment-text" dir="auto">'+esc(item.body)+'</p><label class="adm-field"><span>'+esc(c.reply)+'</span><textarea maxlength="2000" rows="3" data-comment-reply>'+esc(item.reply)+'</textarea></label><div class="adm-actions"><button type="button" class="adm-button primary" data-comment-status="approved">'+esc(c.approve)+'</button><button type="button" class="adm-button secondary" data-comment-status="rejected">'+esc(c.reject)+'</button><button type="button" class="adm-button secondary" data-comment-status="'+item.status+'">'+esc(c.save)+'</button></div></article>').join(''))+'<div class="adm-actions"><button class="adm-button secondary" data-comment-page="-1" '+(page<=1?'disabled':'')+'>'+esc(c.previous)+'</button><span>'+esc(c.page)+' '+page+' / '+Math.max(1,data.pages)+'</span><button class="adm-button secondary" data-comment-page="1" '+(page>=data.pages?'disabled':'')+'>'+esc(c.next)+'</button></div></div>');
   document.querySelector('#admin-comments').addEventListener('click',async event=>{const button=event.target.closest('button');if(!button||saving)return;if(button.dataset.commentFilter){filter=button.dataset.commentFilter;page=1;message='';await load();return;}if(button.dataset.commentPage){page+=Number(button.dataset.commentPage);await load();return;}if(button.dataset.commentStatus){const element=button.closest('[data-comment-id]'),item=data.items.find(v=>v.id===element.dataset.commentId);saving=true;element.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api('/api/admin/comments/'+item.id,{method:'PUT',body:{version:item.version,status:button.dataset.commentStatus,reply:element.querySelector('[data-comment-reply]').value}});message=c.saved;}catch(error){message=error.code==='conflict'?c.conflict:c.error;}finally{saving=false;if(isCurrent())await load();}}});
  }catch{if(isCurrent())frame('<h1>'+esc(c.title)+'</h1><p role="alert">'+esc(c.error)+'</p>');}
 }
 await load();
}
